from html.parser import HTMLParser

VOID = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}

class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack=[]
        self.errors=[]
    def handle_starttag(self, tag, attrs):
        if tag not in VOID:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in VOID:
            return
        if not self.stack:
            self.errors.append(f"unexpected </{tag}> with empty stack at line {self.getpos()[0]}")
            return
        if self.stack[-1]==tag:
            self.stack.pop()
        else:
            # try to find it
            if tag in self.stack:
                while self.stack and self.stack[-1]!=tag:
                    self.errors.append(f"implicit close of <{self.stack[-1]}> before </{tag}> at line {self.getpos()[0]}")
                    self.stack.pop()
                if self.stack: self.stack.pop()
            else:
                self.errors.append(f"stray </{tag}> at line {self.getpos()[0]}")

data=open('/home/agent/workspace/index.html',encoding='utf-8').read()
p=P(); p.feed(data); p.close()
print("Unclosed at end:", p.stack)
print("Errors:", p.errors if p.errors else "none")
print("chars:", len(data))
EOF

